/**
 * ClaraLight Design — tokens.
 *
 * This file is the source of truth for hand-authored design values.
 * Components, verification and spring generation consume these tokens.
 *
 * ClaraLight is a *quiet, layered* design language. Surfaces stack from
 * `background` (window) through `panel` (panes, sheets) to `control`
 * (rows, fields, buttons). Control fills are translucent overlays of the
 * layer beneath, so the same layer reads correctly over any surface.
 * Color is spent sparingly: `accent` marks the primary action and
 * selection, status colors carry meaning, everything else stays neutral.
 *
 * Dark is the default scheme when no explicit scheme class is present.
 *
 * Consume:
 *   @import "tailwindcss";
 *   @import "@claralight-design/react/styles.css";
 */

/* ---------------------------------------------------------------------------
 * Scheme switching
 * ------------------------------------------------------------------------- */

/**
 * `dark` is the default, so it needs no class. `.light` opts into the warm
 * scheme; `.dark` is accepted too, for consumers already using the shadcn
 * convention of toggling a `dark` class on <html>.
 *
 * The runtime values live on `--cl-*` custom properties rather than directly
 * in `@theme`, because Tailwind inlines `@theme` values at build time. The
 * `@theme inline` block below maps them so utilities compile to
 * `var(--cl-background)` and follow the active scheme.
 */
@custom-variant light (&:where(.light, .light *));

/* ---------------------------------------------------------------------------
 * Type ramp
 * ------------------------------------------------------------------------- */

@theme static {
    /*
   * Preferred families and platform fallbacks. Font files are not shipped
   * yet — see fonts/README.md. Fallback metrics depend on installed fonts.
   */
    --font-sans:
        "MiSans VF", "MiSans", "PingFang SC", "SF Pro Text", system-ui, Roboto,
        sans-serif;
    --font-mono:
        "Sarasa Mono SC", ui-monospace, SFMono-Regular, "SF Mono", Menlo,
        monospace;
    --font-display:
        "ChillDINGothic", "MiSans VF", "MiSans", "PingFang SC", system-ui,
        sans-serif;
    --font-serif: "Clara Serif Pro", ui-serif, Georgia, serif;

    /*
   * Step scale. Weights are the ClaraLight intent, not MiSans' axis values —
   * see fonts/README.md for the non-standard VF wght axis (w400 sits at 330).
   * `--text-*--font-weight` therefore only lands correctly once the real
   * font is loaded; with fallback fonts the browser approximates.
   */
    --text-display: 30px;
    --text-display--line-height: 1.2667;
    --text-display--font-weight: 700;
    --text-display--letter-spacing: 0;

    --text-headline: 18px;
    --text-headline--line-height: 1.3333;
    --text-headline--font-weight: 700;
    --text-headline--letter-spacing: -0.55px;

    --text-title: 16px;
    --text-title--line-height: 1.3125;
    --text-title--font-weight: 600;
    --text-title--letter-spacing: -0.4px;

    --text-body: 15px;
    --text-body--line-height: 1.3333;
    --text-body--font-weight: 500;
    --text-body--letter-spacing: -0.5px;

    --text-callout: 14px;
    --text-callout--line-height: 1.3571;
    --text-callout--font-weight: 600;
    --text-callout--letter-spacing: -0.5px;

    --text-label: 13px;
    --text-label--line-height: 1.3077;
    --text-label--font-weight: 700;
    --text-label--letter-spacing: -0.2px;

    --text-caption: 12px;
    --text-caption--line-height: 1.3333;
    --text-caption--font-weight: 400;
    --text-caption--letter-spacing: 0;

    /*
   * Standalone weights, for the places a run of text steps off its ramp entry's
   * own weight. The select's option rows are the case that needs them: they are
   * `callout` at 400 rather than its 600, with the selected row a step heavier
   * at 500 — Flutter's `callout.copyWith(fontWeight: ...)`. A menu is a list to
   * scan, so its rows sit lighter than the field that opened them.
   */
    --font-weight-normal: 400;
    --font-weight-medium: 500;
    --font-weight-semibold: 600;

    /* Numeric readouts: dimensions, memory, time codes. */
    --text-mono: 14px;
    --text-mono--line-height: 1.3;
    --text-mono--font-weight: 400;

    --text-mono-strong: 14px;
    --text-mono-strong--line-height: 1.3;
    --text-mono-strong--font-weight: 600;
}

/* ---------------------------------------------------------------------------
 * Shape (smooth corners, see below)
 * ------------------------------------------------------------------------- */

@theme static {
    --radius-none: 0px; /* square corners; opts the surface out of the shape */
    --radius-control: 8px; /* fields, rows, chips, small buttons */
    --radius-medium: 12px; /* cards, grouped lists, banners, popovers */
    --radius-panel: 18px; /* panels and sidebars */
    --radius-sheet: 36px; /* floating bottom sheets */
    --radius-dialog: 36px; /* modal dialogs */
    --radius-capsule: 999px; /* segmented pills, toolbar buttons */
}

/**
 * Corner smoothing.
 *
 * ClaraLight surfaces use smooth corners ("squircles"), not circular arcs.
 *
 * On the web this is *not* CSS `corner-shape`, and the distinction matters:
 *
 *   corner-shape: superellipse()  a true Lamé superellipse (squircle == n=4).
 *                                 Chromium 139+ only; Safari and Firefox drop
 *                                 the property at parse time.
 *   Figma corner smoothing        cubic Bezier shoulders bracketing a circular
 *                                 arc, `p = (1 + xi) * R` with a `90 * (1 - xi)`
 *                                 residual arc.
 *
 * Those are different curve families and do not coincide. ClaraLight follows
 * the design source, and the design lives in Figma, so the Figma construction
 * is the correct one — it is also the same family as Apple's
 * `cornerCurve = .continuous`, the closest available match to iOS.
 *
 * `corner-shape` is therefore deliberately unused. The shape is produced by
 * `@lisse/react`, which emits the same SVG path in every engine, so Safari,
 * Firefox and Chromium agree pixel for pixel. See `src/lib/squircle.tsx`.
 *
 * `--cl-corner-smoothing` is Figma's xi: 0 gives a plain circular arc
 * identical to `border-radius`, 1 removes the arc entirely and leaves only
 * Beziers. ClaraLight sits at Figma's own default.
 */
@theme static {
    --cl-corner-smoothing: 0.6;
}

/* ---------------------------------------------------------------------------
 * Motion (spring samples generated by scripts/gen-spring.mjs)
 * ------------------------------------------------------------------------- */

@theme static {
    /*
   * Finite transitions. ClaraLight is deliberately quick: 140/160ms, where
   * a typical web design system would sit at 200-300ms.
   */
    --ease-cl-out: cubic-bezier(
        0.23,
        1,
        0.32,
        1
    ); /* strong deceleration, entrances */
    --ease-cl-in: cubic-bezier(
        0.32,
        0,
        0.67,
        0
    ); /* strong acceleration, exits */
    --ease-cl-in-out: cubic-bezier(0.77, 0, 0.175, 1); /* symmetric movement */
    --ease-cl-drawer: cubic-bezier(
        0.32,
        0.72,
        0,
        1
    ); /* iOS-like sheet/drawer */

    /* Tooltip switching uses one motion curve for position and content. */
    --ease-cl-tooltip-morph: var(--ease-cl-in-out);

    /*
   * Derived samples, not hand-authored values. Run `pnpm tokens` after
   * changing the spring parameter tokens below. Overlay time is normalized
   * progress; press time is seconds mapped through its release duration.
   */
    --ease-cl-spring-overlay: linear(0, 0.0132 1.85%, 0.0481 3.7%, 0.0986 5.56%, 0.1595 7.41%, 0.2268 9.26%, 0.2973 11.11%, 0.3683 12.96%, 0.438 14.81%, 0.5048 16.67%, 0.5679 18.52%, 0.6265 20.37%, 0.6803 22.22%, 0.729 24.07%, 0.7728 25.93%, 0.8115 27.78%, 0.8456 29.63%, 0.8753 31.48%, 0.9009 33.33%, 0.9228 35.19%, 0.9413 37.04%, 0.9567 38.89%, 0.9695 40.74%, 0.9799 42.59%, 0.9883 44.44%, 0.995 46.3%, 1.0001 48.15%, 1.004 50%, 1.0069 51.85%, 1.0089 53.7%, 1.0101 55.56%, 1.0108 57.41%, 1.0111 59.26%, 1.011 61.11%, 1.0107 62.96%, 1.0101 64.81%, 1.0095 66.67%, 1.0087 68.52%, 1.008 70.37%, 1.0072 72.22%, 1.0064 74.07%, 1.0057 75.93%, 1.0049 77.78%, 1.0043 79.63%, 1.0037 81.48%, 1.0031 83.33%, 1.0026 85.19%, 1.0022 87.04%, 1.0018 88.89%, 1.0015 90.74%, 1.0012 92.59%, 1.0009 94.44%, 1.0007 96.3%, 1.0005 98.15%, 1);
    --ease-cl-spring-press: linear(0, 0.0172 1.52%, 0.0654 3.03%, 0.1391 4.55%, 0.2326 6.06%, 0.3403 7.58%, 0.4568 9.09%, 0.5771 10.61%, 0.6966 12.12%, 0.8114 13.64%, 0.9182 15.15%, 1.0145 16.67%, 1.0982 18.18%, 1.1682 19.7%, 1.2238 21.21%, 1.2649 22.73%, 1.2919 24.24%, 1.3058 25.76%, 1.3076 27.27%, 1.2988 28.79%, 1.281 30.3%, 1.256 31.82%, 1.2255 33.33%, 1.1911 34.85%, 1.1547 36.36%, 1.1175 37.88%, 1.0811 39.39%, 1.0464 40.91%, 1.0145 42.42%, 0.9862 43.94%, 0.9618 45.45%, 0.9417 46.97%, 0.9261 48.48%, 0.915 50%, 0.9081 51.52%, 0.9052 53.03%, 0.9058 54.55%, 0.9095 56.06%, 0.9158 57.58%, 0.9242 59.09%, 0.9341 60.61%, 0.9449 62.12%, 0.9563 63.64%, 0.9677 65.15%, 0.9788 66.67%, 0.9892 68.18%, 0.9987 69.7%, 1.007 71.21%, 1.0141 72.73%, 1.0198 74.24%, 1.0241 75.76%, 1.0271 77.27%, 1.0288 78.79%, 1.0293 80.3%, 1.0287 81.82%, 1.0273 83.33%, 1.0251 84.85%, 1.0224 86.36%, 1.0192 87.88%, 1.0158 89.39%, 1.0123 90.91%, 1.0088 92.42%, 1.0054 93.94%, 1.0023 95.45%, 0.9995 96.97%, 0.997 98.48%, 1);

    /* Perceptual surfacing of frosted floating layers. */
    --blur-frost: 36px;
}

/* ---------------------------------------------------------------------------
 * Control geometry and interaction
 * ------------------------------------------------------------------------- */

@theme static {
    /* Numeric spacing utilities derive from this shared unit. */
    --spacing: 4px;
    --container-lg: 32rem;
    --spacing-control-sm: 28px;
    --spacing-control-md: 36px;
    --spacing-control-lg: 44px;
    --spacing-icon-sm: 15px;
    --spacing-icon-md: 18px;
    --spacing-icon-lg: 24px;
    --radius-item: 6px;

    --text-button: 17px;
    --text-button--line-height: 22px;
    --text-button--font-weight: 500;
    --text-button--letter-spacing: -0.43px;

    --cl-press-scale-sm: 1.0714;
    --cl-press-scale-md: 1.0556;
    --cl-press-scale-lg: 1.0455;
    --cl-duration-fast: 140ms;
    --cl-duration-surface: 160ms;
    --cl-duration-press: 170ms;
    --cl-duration-release: 550ms;
    --cl-duration-enter: 250ms;
    --cl-duration-morph: 380ms;
    --cl-duration-exit: 110ms;
    --cl-duration-reduced: 125ms;
    --cl-duration-tooltip-morph: 180ms;
    --cl-duration-tooltip-tail: 60ms;
    --cl-duration-tooltip-content-exit: 90ms;
    --cl-tooltip-content-scale: 0.98;
    --cl-tooltip-content-blur: 5px;
    --cl-tooltip-content-offset: 8px;
    --cl-tooltip-content-offset-negative: -8px;
    --ease-cl-press-in: cubic-bezier(0.25, 1, 0.5, 1);
    --cl-focus-width: 2px;
    --cl-focus-offset: 2px;
    --cl-enter-scale: 0.95;

    --cl-spring-overlay-omega: 9.2;
    --cl-spring-overlay-zeta: 0.82;
    --cl-spring-overlay-sample-duration: 450ms;
    --cl-spring-press-mass: 1;
    --cl-spring-press-stiffness: 520;
    --cl-spring-press-damping: 16;

    /*
   * The select panel's reveal, read by `lib/reveal.tsx` rather than sampled
   * into a `linear()`: that leg is driven per frame in JS, because the shape's
   * `clip-path` and its SVG outline have to be regenerated at every size the
   * box passes through, and a CSS timing function cannot be read back.
   *
   * Same physical system as the two above, in the same normalized-progress
   * units as `--cl-spring-overlay-*`: `omega` is the undamped frequency over
   * the leg, so the seconds live in `--cl-duration-morph`. These values are
   * the Flutter select's `SpringDescription(mass: 1, stiffness: 700,
   * damping: 30)` on that clock — omega = sqrt(700) * 0.38, zeta =
   * 30 / (2 * sqrt(700)) — which overshoots ~11%, far looser than the overlay
   * spring. The panel arriving with a visible settle is the point.
   */
    --cl-spring-select-omega: 10.05;
    --cl-spring-select-zeta: 0.567;

    --cl-hover-base-weight: 92%;
    --cl-hover-tint: #ffffff;
    --cl-select-max-width: 28rem;
    /*
   * How tall the options list may get: the screen, less the margin the panel
   * keeps from its edges and less the panel's own chrome around the list — its
   * 6px of padding and the hairline `.cl-frost` draws, top and bottom, so that
   * it is the *panel* that fits the screen.
   *
   * There is deliberately no smaller number here. Flutter's aligned branch is
   * `min(panelContentHeight, availableHeight)` and nothing else: a long menu
   * grows until it fills the screen. A fixed cap changes what the menu *is* —
   * the selected option can no longer be shown with its neighbours around it,
   * and the placement has to start trading the row's position against the
   * panel's, which is a decision a menu should never have to make. Override
   * this token to cap a particular select; the placement handles it.
   */
    --cl-select-max-height: calc(
      100dvh - var(--cl-select-screen-margin) * 2 - var(--cl-select-panel-padding) * 2 - 2px
    );
    --cl-select-side-offset: 6px;
    /*
   * The options panel's own geometry, which does not follow the control size:
   * a denser select has shorter rows, not a tighter panel around them. Both are
   * the Flutter select's constants (`_panelPadding`, `_panelHorizontalPadding`
   * and the option row's own `EdgeInsets.symmetric(horizontal: 10)`).
   */
    --cl-select-panel-padding: 6px;
    --cl-select-row-padding: 10px;
    /*
   * The trigger's stacked chevrons. Taller than wide, and not on the icon ramp:
   * the two heads need vertical room between them and none at the sides, so the
   * glyph is its own box rather than a square that happens to contain it.
   */
    /* The closest the options panel comes to the edge of the viewport. */
    --cl-select-screen-margin: 8px;
    /*
   * How far the options list dissolves at its top and bottom. Shorter than the
   * scroll area's own 24px, because the band is measured against a row: at 24 a
   * 28px row at the edge is fading across almost its whole height and reads as
   * disabled rather than as clipped. Flutter's select makes the same reduction
   * against `CLList`'s identical default.
   */
    --cl-select-scroll-edge: 16px;
    --cl-select-chevrons-width: 9px;
    --cl-select-chevrons-height: 14px;

    /*
   * Scroll area.
   *
   * `edge` is how far a side fades over; `blur` is the Gaussian sigma that
   * fade reaches at the very edge. Setting one side's edge to zero removes
   * both the fade and the blur there, so the four sides are independently
   * switchable without a prop.
   *
   * The sides are logical, because the overflow state they follow is: in a
   * vertical LTR area `block-start` is the top and `block-end` the bottom, and
   * an RTL area needs no overrides at all.
   */
    --cl-scroll-edge: 24px;
    --cl-scroll-edge-block-start: var(--cl-scroll-edge);
    --cl-scroll-edge-block-end: var(--cl-scroll-edge);
    --cl-scroll-edge-inline-start: var(--cl-scroll-edge);
    --cl-scroll-edge-inline-end: var(--cl-scroll-edge);
    --cl-scroll-blur: 5px;

    /*
   * The three-layer ramp that stands in for the continuously varying sigma a
   * shader would use: each layer reaches half as far into the band as the one
   * before it and blurs half as hard, so strength falls off geometrically from
   * the very edge. The strongest layer is `--cl-scroll-blur` over the full
   * band, so it needs no multiplier of its own.
   */
    --cl-scroll-blur-mid: 0.5;
    --cl-scroll-blur-far: 0.25;
    --cl-scroll-reach-near: 25%;
    --cl-scroll-reach-mid: 50%;

    /* The thumb is `--cl-selection`; `inset` keeps both tracks clear of a
     * surface's own padding, and `margin` shortens the thumb within its track. */
    --cl-scrollbar-thickness: 4px;
    --cl-scrollbar-margin: 2px;
    --cl-scrollbar-inset: 0px;
    --cl-scrollbar-fade-delay: 300ms;
    --cl-scrollbar-fade-duration: 180ms;

    /*
   * Anchored overlays (popover, tooltip).
   *
   * The arrow is not a separate element: it is spliced into the surface's own
   * smooth-corner path, so `--cl-arrow-*` are the tail's geometry inside that
   * path rather than the size of a box. `extent` is how far the tail reaches
   * past the body; `width` is its full base along the body edge.
   *
   * `gap` is measured from the tail's tip, not the body, so an overlay sits the
   * same distance from its anchor whether or not it draws an arrow.
   */
    --cl-arrow-extent: 7px;
    --cl-arrow-width: 24px;
    --cl-anchor-gap: 4px;
    --cl-anchor-margin: 8px;
    --cl-popover-padding: 12px;
    --cl-tooltip-padding-x: 10px;
    --cl-tooltip-padding-y: 6px;
    --cl-tooltip-delay: 450ms;
    --cl-tooltip-close-delay: 50ms;
    /* Reopening another tooltip within this window skips the dwell entirely. */
    --cl-tooltip-grace: 500ms;

    /*
   * The numeric field's stepper and its scrub readout.
   *
   * The strip is wider than the chevrons it holds: the buttons sit against the
   * value, and the remainder is the field's trailing inset, which keeps the
   * chevrons off the rounded corner. One chevron button is `step-width` across
   * the strip and `step-height` along it, so two of them stack inside it — and
   * a horizontal stepper swaps the pair rather than needing its own sizes.
   *
   * The readout's padding is its own rather than the popover's: it holds one
   * number at display size, so it is inset further than a surface of prose.
   */
    --cl-number-stepper-width: 24px;
    --cl-number-step-width: 18px;
    --cl-number-step-height: 10px;
    --cl-number-readout-padding-x: 16px;
    --cl-number-readout-padding-y: 10px;

    /*
   * The progress bar.
   *
   * Thickness is a doubling ladder rather than the control heights: a progress
   * bar is a line, not a box, so the three steps are the hairline under a
   * toolbar, the default row, and the bar a sheet gives a line of its own.
   *
   * `gap` is the distance the track keeps from the active indicator, which is
   * what makes the rail read as two pieces rather than one bar filling up. It
   * collapses on its own as either end runs out of room — see `progress.css`
   * — so it needs no second, smaller value for the ends of the range.
   *
   * `extent` is the whole of the rail, and it is a token because every position
   * in the component is a fraction of it: the segments are laid out as
   * `fraction * extent`, which is the same arithmetic the design's indicator
   * does over a canvas width. It is also what caps a segment's fill at the
   * rail's own thickness, so a short segment stays round.
   *
   * The cycle is the one duration in ClaraLight that is not quick. It is not a
   * transition: an indeterminate bar is a loop that has to read as unhurried
   * work rather than as something repeatedly failing and restarting.
   */
    --spacing-progress-sm: 2px;
    --spacing-progress-md: 4px;
    --spacing-progress-lg: 8px;
    --cl-progress-gap: 4px;
    --cl-progress-extent: 100%;
    --cl-duration-progress: 1750ms;
}

@theme inline static {
    --color-accent-hover: color-mix(
        in oklab,
        var(--cl-accent) var(--cl-hover-base-weight),
        var(--cl-hover-tint)
    );
    --color-floating-hover: color-mix(
        in oklab,
        var(--cl-floating) var(--cl-hover-base-weight),
        var(--cl-hover-tint)
    );
    --color-danger-hover: color-mix(
        in oklab,
        var(--cl-danger) var(--cl-hover-base-weight),
        var(--cl-hover-tint)
    );
}

/* ---------------------------------------------------------------------------
 * Shadow ladder
 * ------------------------------------------------------------------------- */

/**
 * Two-layer shadows: a wide soft ambient pass and a tight contact pass.
 */
@theme static {
    --shadow-frost:
        0 16px 48px -12px rgb(0 0 0 / 0.55), 0 2px 8px -2px rgb(0 0 0 / 0.32);
    --shadow-panel:
        0 8px 32px -8px rgb(0 0 0 / 0.42), 0 1px 3px rgb(0 0 0 / 0.24);
    --shadow-dialog:
        0 32px 72px -16px rgb(0 0 0 / 0.6), 0 4px 16px -4px rgb(0 0 0 / 0.36);
}

/* ---------------------------------------------------------------------------
 * Scheme tokens
 * ------------------------------------------------------------------------- */

/**
 * `@theme inline` so utilities compile to `var(--cl-*)` and pick up whichever
 * scheme is active, instead of being inlined at build time.
 *
 * `static` keeps every variable in the output even when no utility happens to
 * reference it. Tailwind drops unused theme variables by default, which is a
 * reasonable default for an app and the wrong one for a design system: these
 * names are the public API, and consumers read them at runtime
 * (`getComputedStyle(el).getPropertyValue("--radius-sheet")`) or reference them
 * from hand-written CSS. A token that silently disappears because the current
 * component set does not use it is a break nobody can see.

 */
@theme inline static {
    /* --- Layered surface stack --- */
    --color-background: var(--cl-background); /* window / canvas */
    --color-panel: var(--cl-panel); /* panes, sheets, sidebars */
    --color-frost: var(--cl-frost); /* translucent wash under a backdrop blur */
    --color-control: var(--cl-control); /* rows, fields, buttons, chips */
    --color-control-highlight: var(
        --cl-control-highlight
    ); /* hovered / gently raised */
    --color-floating: var(
        --cl-floating
    ); /* dark fill over arbitrary canvas content */
    --color-on-floating: var(--cl-on-floating);
    --color-selection: var(
        --cl-selection
    ); /* selected row / segment, scrollbar thumb */
    --color-track: var(
        --cl-track
    ); /* recessed track behind segmented / slider / switch */

    /* --- Lines --- */
    --color-separator: var(
        --cl-separator
    ); /* hairline between rows and groups */
    --color-outline: var(--cl-outline); /* 1px around controls and dialogs */
    --color-outline-strong: var(
        --cl-outline-strong
    ); /* floating panels and sheets */

    /* --- Foreground ramp --- */
    --color-foreground: var(
        --cl-foreground
    ); /* primary: titles, selected rows */
    --color-foreground-secondary: var(
        --cl-foreground-secondary
    ); /* row and body text */
    --color-foreground-tertiary: var(
        --cl-foreground-tertiary
    ); /* subtitles, units, prefixes */
    --color-foreground-hint: var(
        --cl-foreground-hint
    ); /* section headers, placeholders */
    --color-foreground-disabled: var(--cl-foreground-disabled);

    /* --- Accent --- */
    --color-accent: var(--cl-accent);
    --color-accent-background: var(--cl-accent-background);
    --color-on-accent: var(--cl-on-accent);
    --color-selection-accent: var(--cl-selection-accent);

    /* --- Status --- */
    --color-success: var(--cl-success);
    --color-warning: var(--cl-warning);
    --color-warning-background: var(--cl-warning-background);
    --color-danger: var(--cl-danger);
    --color-danger-background: var(--cl-danger-background);
    --color-on-danger: var(--cl-on-danger);

    /* --- Scrim --- */
    --color-scrim: var(--cl-scrim);
}

/**
 * Dark — the default scheme. Explicit `rgb(... / alpha)` keeps translucent
 * layers readable and editable.
 */
:root,
.dark {
    --cl-background: #191919;
    --cl-panel: #111111;
    --cl-frost: rgb(22 22 22 / 0.749);

    --cl-control: rgb(255 255 255 / 0.102);
    --cl-control-highlight: rgb(255 255 255 / 0.149);
    --cl-floating: rgb(0 0 0 / 0.608);
    --cl-on-floating: #ffffff;
    --cl-selection: rgb(255 255 255 / 0.161);
    --cl-track: rgb(255 255 255 / 0.102);

    --cl-separator: rgb(255 255 255 / 0.102);
    --cl-outline: rgb(255 255 255 / 0.149);
    --cl-outline-strong: rgb(255 255 255 / 0.302);

    --cl-foreground: #ffffff;
    --cl-foreground-secondary: rgb(255 255 255 / 0.898);
    --cl-foreground-tertiary: rgb(255 255 255 / 0.749);
    --cl-foreground-hint: rgb(255 255 255 / 0.4);
    --cl-foreground-disabled: rgb(255 255 255 / 0.349);

    --cl-accent: #0090ff;
    --cl-accent-background: rgb(0 136 246 / 0.325);
    --cl-on-accent: #ffffff;
    --cl-selection-accent: #3e63dd;

    --cl-success: #30d158;
    --cl-warning: #ffba18;
    --cl-warning-background: rgb(244 209 0 / 0.086);
    --cl-danger: #e5484d;
    --cl-danger-background: rgb(243 0 13 / 0.078);
    --cl-on-danger: #ffffff;

    --cl-scrim: rgb(0 0 0 / 0.451);

    color-scheme: dark;
}

/**
 * Light — a warm scheme: cream paper and near-black with a brown cast,
 * rather than neutral grey.
 */
.light {
    --cl-background: #f9f6ee;
    --cl-panel: #f4f2ea;
    --cl-frost: rgb(255 255 255 / 0.612);

    --cl-control: rgb(176 160 148 / 0.102);
    --cl-control-highlight: rgb(176 160 148 / 0.2);
    --cl-floating: rgb(255 255 255 / 0.612);
    --cl-on-floating: #160a01;
    --cl-selection: rgb(176 160 148 / 0.102);
    --cl-track: rgb(176 160 148 / 0.102);

    --cl-separator: rgb(22 10 1 / 0.102);
    --cl-outline: rgb(22 10 1 / 0.161);
    --cl-outline-strong: rgb(22 10 1 / 0.302);

    --cl-foreground: #160a01;
    /* Secondary text is slightly more opaque than in the dark scheme. */
    --cl-foreground-secondary: rgb(22 10 1 / 0.902);
    --cl-foreground-tertiary: rgb(22 10 1 / 0.749);
    --cl-foreground-hint: rgb(22 10 1 / 0.62);
    --cl-foreground-disabled: rgb(22 10 1 / 0.322);

    --cl-accent: #0090ff;
    --cl-accent-background: rgb(0 144 255 / 0.161);
    --cl-on-accent: #ffffff;
    --cl-selection-accent: #3e63dd;

    --cl-success: #34c759;
    --cl-warning: #c7871e;
    --cl-warning-background: rgb(244 209 0 / 0.086);
    --cl-danger: #e5484d;
    --cl-danger-background: rgb(243 0 13 / 0.078);
    --cl-on-danger: #ffffff;

    --cl-scrim: rgb(0 0 0 / 0.349);

    color-scheme: light;
}

/* ---------------------------------------------------------------------------
 * Reduced motion
 * ------------------------------------------------------------------------- */

/**
 * Keep a short fade under reduced motion rather than removing feedback
 * entirely, so state changes stay legible.
 */
@media (prefers-reduced-motion: reduce) {
    :root {
        --ease-cl-spring-overlay: linear(0, 1);
        --ease-cl-spring-press: linear(0, 1);
    }

    *,
    ::before,
    ::after {
        animation-duration: var(--cl-duration-reduced) !important;
        animation-iteration-count: 1 !important;
        transition-duration: var(--cl-duration-reduced) !important;
        transition-timing-function: var(--ease-cl-out) !important;
        scroll-behavior: auto !important;
    }
}

/**
 * ClaraLight Design — component primitives.
 *
 * Tokens live in `theme.css`. This file holds the handful of behaviours that
 * are part of the design language itself and are too structural to express as
 * a Tailwind class string: the signature press interaction, the frosted
 * floating surface, and the focus ring.
 *
 * Kept as CSS rather than utilities so a component's class list stays
 * readable and the physics stay in one place.
 *
 * Everything here is used by every build. What only one or two components need
 * ships beside them instead — `anchored.css` for Popover and Tooltip,
 * `tooltip.css` for the shared-tooltip morph, `scroll-area.css` for the scroll
 * area's edges and scrollbars, `progress.css` for the progress bar's segments —
 * so a copy-in project that skips those components does not carry their CSS.
 * The npm entry point pulls in all five.
 *
 *   @import "tailwindcss";
 *   @import "@claralight-design/react/styles.css";
 */

/* Tailwind's built-in shadow compiler expands token values into literal
 * --tw-shadow declarations. Keep these public utilities runtime-bound so a
 * scoped --shadow-* override also reaches Squircle's SVG effect reader. */
@utility shadow-frost {
  box-shadow: var(--shadow-frost);
}

@utility shadow-panel {
  box-shadow: var(--shadow-panel);
}

@utility shadow-dialog {
  box-shadow: var(--shadow-dialog);
}

@layer components {
  /* -------------------------------------------------------------------------
   * Press
   * ---------------------------------------------------------------------- */

  /**
   * The signature ClaraLight press:
   * the control scales *up* while held, then springs back with overshoot on
   * release.
   *
   * CSS picks transition values from the state being entered, which is exactly
   * the behaviour we want and needs no JS:
   *
   *   press    -> element becomes :active          -> 170ms easeOutQuart
   *   release  -> element stops being :active      -> 550ms spring
   *
   * The two legs therefore live in different rules. Overriding the duration
   * through custom properties keeps a single `transition` shorthand valid
   * instead of fighting `transition-property` ordering.
   *
   * Set `--cl-press-scale` using the size tokens so shorter controls move
   * further in relative terms and every size feels equally responsive.
   */
  .cl-press {
    --cl-press-scale: var(--cl-press-scale-lg);
    --cl-press-duration: var(--cl-duration-release);
    --cl-press-ease: var(--ease-cl-spring-press);

    transition:
      color var(--cl-duration-press) var(--ease-cl-out),
      background-color var(--cl-duration-press) var(--ease-cl-out),
      border-color var(--cl-duration-press) var(--ease-cl-out),
      box-shadow var(--cl-duration-press) var(--ease-cl-out),
      opacity var(--cl-duration-press) var(--ease-cl-out),
      outline-color var(--cl-duration-fast) var(--ease-cl-out),
      transform var(--cl-press-duration) var(--cl-press-ease);
  }

  /* Disabled shaped children can still leave their wrapper :active when
   * pointer-events are suppressed. Guard both wrapped and standalone controls. */
  .cl-press:active:not(:where(:disabled, [disabled], [data-disabled], [aria-disabled="true"])):not(:has(> :where(:disabled, [disabled], [data-disabled], [aria-disabled="true"]))) {
    --cl-press-duration: var(--cl-duration-press);
    --cl-press-ease: var(--ease-cl-press-in);
    transform: scale(var(--cl-press-scale));
  }

  /**
   * ClaraLight drops the scale entirely under reduced motion rather than
   * shrinking it, and keeps the opacity/surface feedback.
   */
  @media (prefers-reduced-motion: reduce) {
    .cl-press:active {
      transform: none;
    }
  }

  /* -------------------------------------------------------------------------
   * Frosted floating surface
   * ---------------------------------------------------------------------- */

  /**
   * Menus, popovers, dialogs and sheets. The blur, outline and shadow all
   * consume theme tokens; Squircle handles their smooth-corner geometry.
   */
  .cl-frost {
    background-color: var(--cl-frost);
    -webkit-backdrop-filter: blur(var(--blur-frost));
    backdrop-filter: blur(var(--blur-frost));
    border: 1px solid var(--cl-outline-strong);
    box-shadow: var(--shadow-frost);
  }

  /** Same layer, without the shadow — for surfaces stacked inside a panel. */
  .cl-panel {
    background-color: var(--cl-panel);
    border: 1px solid var(--cl-outline);
  }

  /* -------------------------------------------------------------------------
   * Smooth-corner root
   * ---------------------------------------------------------------------- */

  /**
   * The wrapper `Squircle` renders around a clipped element.
   *
   * It exists because Lisse re-renders borders and shadows as SVG overlays,
   * which have to be appended to a positioned element that tightly wraps the
   * shape. Two consequences worth knowing:
   *
   * 1. **Transforms belong here, not on the shape.** The overlays are siblings
   *    of the clipped element, so anything that moves the shape without moving
   *    the wrapper tears the 1px border away from the edge. The press scale and
   *    the dialog entrance therefore live on this element, which also reads
   *    better: fill, border and shadow scale as one object.
   *
   * 2. **The focus ring lives here too**, because `clip-path` crops `outline` to
   *    nothing on the shape itself — measured, a 2px ring at 2px offset goes
   *    from 436 lit pixels to 0. `:has()` lets the browser's own
   *    `:focus-visible` heuristic drive it, so there is no JS focus state and
   *    clicks still do not flash a ring.
   *
   * The radius is carried in a custom property so the ring clears the shape at
   * every radius token; `Squircle` sets it.
   */
  .cl-squircle-root {
    border-radius: calc(var(--cl-squircle-radius, 0px) + var(--cl-focus-offset));
    outline: var(--cl-focus-width) solid transparent;
    outline-offset: var(--cl-focus-offset);
    /*
     * Deliberately no `transition` here. `.cl-press` and `.cl-squircle-root`
     * very often sit on the same element, and a second `transition` declaration
     * wins by source order — which silently replaced the press spring with an
     * outline fade. `.cl-press` owns the transition and lists `outline-color`
     * alongside its own properties.
     */
  }

  /**
   * A surface whose radius measured 0.
   *
   * At radius 0 the smooth-corner construction is a rectangle, so `Squircle`
   * stops generating one: no `path()` regenerated on every resize, no SVG
   * overlay for the border and shadow, and the native `border` and
   * `box-shadow` paint themselves instead of being masked out and redrawn.
   *
   * What the generated clip was *also* doing has to stay, which is why this
   * rule exists rather than nothing at all. `clip-path` clips the content and
   * establishes a backdrop root, and the scroll area's edge blur depends on
   * that root to see only the surface's own fill and its scrolled content.
   * Measured in Chromium against a checkerboard behind the surface, on a scale
   * where 127 is the pattern untouched and 0 is it blurred flat: `clip-path`
   * 127, `will-change: opacity` 127, `filter: opacity(1)` 127 — and
   * `isolation: isolate` 0, `overflow: clip` 0, `contain: paint` 0. The three
   * that work all cost more than a rectangle clip except the rectangle clip
   * itself, so that is what a flat surface keeps.
   *
   * `inset(0)` and not `path()`: it is a static declaration no script has to
   * recompute, and a rectangle is the clip shape engines handle best.
   */
  [data-cl-squircle][data-cl-flat] {
    clip-path: inset(0);
  }

  .cl-squircle-root:has(> [data-cl-squircle]:focus-visible) {
    outline-color: var(--cl-accent);
  }

  /**
   * Text fields and selects take focus on click, and the user needs to see which
   * field got it, so they cannot use `:focus-visible`.
   *
   * `:focus-within` rather than `:focus`, because a field is not always the
   * element that takes focus: a numeric field is a group holding an input and
   * two stepper buttons, and the ring belongs to the whole control. It still
   * matches the element itself, so a plain `Input` is unaffected.
   */
  .cl-squircle-field:has(> [data-cl-squircle]:focus-within) {
    outline-color: var(--cl-accent);
  }

  /* -------------------------------------------------------------------------
   * Floating-layer entrance
   * ---------------------------------------------------------------------- */

  /**
   * Base UI observes animations on the popup element when deciding when to
   * unmount. ClaraLight deliberately animates the wrapper so the fill, SVG
   * outline and shadow stay together, which puts the visible transition one
   * level above that observer.
   *
   * This non-visual animation is the bridge between the two contracts. It runs
   * only while Base UI marks the popup as ending and animates a custom property,
   * never opacity, transform or layout. The wrapper remains the only thing that
   * moves; Base UI now has a real animation on the popup whose completion it
   * can await before `forceUnmount`.
   */
  @keyframes cl-overlay-exit-sentinel {
    from {
      --cl-overlay-exit-sentinel: 0;
    }
    to {
      --cl-overlay-exit-sentinel: 1;
    }
  }

  .cl-exit-sentinel[data-ending-style] {
    animation: cl-overlay-exit-sentinel var(--cl-duration-exit) linear both;
  }

  /**
   * Menus, popovers, dialogs and sheets.
   *
   * The transition runs on the **wrapper**, not on the popup, because the popup
   * is the clipped element and the SVG border and shadow overlays are its
   * siblings on the wrapper. Scaling the popup alone would leave the 1px border
   * and the shadow at their final size — 5% of a 512px dialog is 25px, which is
   * very visible over a 250ms entrance.
   *
   * Base UI drives this from the popup's `data-starting-style` /
   * `data-ending-style`; `:has()` lifts that state onto the wrapper so the whole
   * assembly — fill, border and shadow — moves as one object.
   *
   * Two durations, because a scrim that takes as long as the spring makes the
   * page behind it feel stuck. The ClaraLight springs are `Curve` equivalents,
   * so `linear()` encodes the shape and the component owns the timing.
   */
  .cl-enter-root {
    transition:
      opacity var(--cl-duration-surface) var(--ease-cl-out),
      scale var(--cl-duration-enter) var(--ease-cl-spring-overlay);
  }

  .cl-enter-root:has(> [data-starting-style]),
  .cl-enter-root:has(> [data-ending-style]) {
    opacity: 0;
    scale: var(--cl-enter-scale);
  }

  .cl-enter-root:has(> [data-ending-style]) {
    transition:
      opacity var(--cl-duration-surface) var(--ease-cl-out),
      scale var(--cl-duration-exit) var(--ease-cl-spring-overlay);
  }

  /**
   * A layer whose geometry belongs to `useSurfaceMorph`.
   *
   * The 5% nudge belongs to a layer that has no fixed point to grow from. A layer
   * that has one is carried by a projective quad, and the nudge would be a second,
   * coarser claim on the same geometry — measured through it, the morph's own
   * resting box lands 5% small, and therefore that far off the trigger.
   *
   * Opacity moves here for the same reason: the morph reveals the content from
   * the same progress that carries the geometry, so the two legs cannot disagree.
   * Left to a transition, the `ease-out` fade would empty the layer in the first
   * half of a dismissal and leave the collapse back to the trigger unwatchable.
   *
   * Declared in the markup rather than set from the effect that drives the morph,
   * because *changing* a computed `scale` is itself what starts the transition
   * above: a component that reported itself as morphed one frame late would
   * animate the nudge it was replacing. Present from the first style resolution,
   * neither value changes and neither transition starts. This block has to stay
   * after the two above it — it replaces their `transition` at equal specificity.
   *
   * Scoped to `no-preference` so reduced motion keeps the fade it is asking for,
   * which is the CSS leg with no geometry underneath it.
   */
  @media (prefers-reduced-motion: no-preference) {
    .cl-enter-root.cl-morph,
    .cl-enter-root.cl-morph:has(> [data-starting-style]),
    .cl-enter-root.cl-morph:has(> [data-ending-style]) {
      transition-property: scale;
      transition-duration: var(--cl-duration-enter);
      transition-timing-function: var(--ease-cl-spring-overlay);
      opacity: 1;
      scale: none;
    }
  }

  /**
   * The select panel's scrolling list.
   *
   * The cap is the screen, not the room below the trigger — `--cl-select-max-
   * height` carries that arithmetic. A panel that aligns its selected option
   * with the trigger is placed by its *contents*, so it may sit almost anywhere
   * on the screen, and clamping it to the space under the field would leave a
   * select near the bottom of the page opening a menu a few rows tall for no
   * reason the person can see. Flutter's aligned branch gives the panel the
   * whole safe area for exactly this reason.
   */
  .cl-select-list {
    max-height: var(--cl-select-max-height);
  }

  /**
   * The same list when the panel is *not* aligning its selected option, and so
   * opens against the trigger like any other popup.
   *
   * Then the room below (or above) the field is the real constraint, and
   * `--available-height` is Base UI's measurement of it. That variable is
   * written **after** the positioner has resolved — which is after Base UI has
   * measured this element to decide where the panel goes. Referenced without a
   * fallback, the whole `min()` is invalid for that first measurement, the cap
   * does not exist, and a list of 500 rows reports its full unconstrained
   * height; Base UI then sizes the overlap against an 18000px panel and lands it
   * near the top of the viewport. So the screen cap stands in for the
   * measurement until the measurement exists, and clamps it afterwards.
   */
  .cl-select-list[data-cl-fit="anchor"] {
    max-height: min(
      var(--available-height, var(--cl-select-max-height)),
      var(--cl-select-max-height)
    );
  }

  /**
   * A selected option row with the pointer on it.
   *
   * Every other row swaps one fill for another, which Tailwind states directly.
   * This one cannot: the hover fill has to sit *over* the accent wash, not
   * replace it, because both are translucent and the row reads as the selected
   * one that is also being pointed at. Replacing the fill loses the selection
   * for as long as the pointer is there; mixing the two colours lands on a third
   * colour that is in neither palette.
   *
   * `background-image` paints over `background-color`, so the pair composites
   * exactly the way `Color.alphaBlend(control, accentBackground)` does in
   * Flutter — one colour over the other, in that order, at their own alphas.
   */
  .cl-select-row[data-selected][data-highlighted] {
    background-image: linear-gradient(var(--cl-control), var(--cl-control));
  }

  /**
   * The one frame a reveal cannot draw.
   *
   * `.cl-morph` hands the geometry *and* the opacity to the driver, which is
   * right for a layer the driver can place on the frame it mounts. A reveal
   * cannot: its first measurement has to wait for the positioner to resolve
   * `--anchor-width`, because the wrapper's own `min-width` is written in terms
   * of it — see `lib/reveal.tsx`. That leaves exactly one frame where the panel
   * is mounted at its resting size and nothing has claimed it yet.
   *
   * Base UI's starting state covers that frame and no other, so the layer is
   * hidden for it and the driver owns every frame after. Scoped to the clipped
   * element rather than the wrapper because that is where Base UI writes the
   * attribute, and the wrapper's own opacity is the driver's to hold.
   */
  .cl-reveal[data-starting-style] {
    opacity: 0;
  }

  /* The dialog/select wrapper also fades for `--cl-duration-surface`; its
   * sentinel has to cover that longer leg, not just the 110ms scale return. */
  .cl-enter-root > .cl-exit-sentinel[data-ending-style] {
    animation-duration: var(--cl-duration-surface);
  }

  @media (prefers-reduced-motion: reduce) {
    .cl-enter-root {
      transition: opacity var(--cl-duration-reduced) var(--ease-cl-out);
    }

    .cl-enter-root:has(> [data-starting-style]),
    .cl-enter-root:has(> [data-ending-style]) {
      scale: none;
      opacity: 0;
    }
  }

  /* -------------------------------------------------------------------------
   * Focus
   * ---------------------------------------------------------------------- */

  /**
   * ClaraLight marks focus with the accent color. Uses `outline` rather than a
   * ring so the indicator never shifts layout and survives `overflow: hidden`
   * ancestors, and stays visible on both schemes because accent is the same
   * blue in each.
   *
   * Two variants, because the trigger differs:
   *   cl-focus        buttons and other pointer-activated controls, which
   *                   should not flash an indicator on mouse click
   *   cl-focus-field  text fields and selects, where focus follows the click
   *                   and the user needs to see which field took it
   */
  .cl-focus,
  .cl-focus-field {
    outline: var(--cl-focus-width) solid transparent;
    outline-offset: var(--cl-focus-offset);
  }

  .cl-focus:focus-visible,
  .cl-focus-field:focus {
    outline-color: var(--cl-accent);
  }
}

import type { ClassValue } from "cn";
import { createCn } from "cn/config";

/**
 * Tailwind's `text-*`, `shadow-*` and `ring-*` prefixes each cover two
 * unrelated utility groups — a value (`text-lg` font size, `shadow-lg`, ...)
 * and a color (`text-red-500`, `shadow-red-500`, ...). Class-merge libraries
 * decide which group a class belongs to by recognising the value, and they
 * cannot recognise a token that only exists in ClaraLight's `@theme`.
 *
 * The failure is silent and destructive. `text-title` reads as a *color* to
 * both `cn` and `tailwind-merge`, so:
 *
 *   cn("text-title text-foreground")  ->  "text-foreground"
 *
 * The font size is gone, with no warning. Every ClaraLight type step is
 * affected because they are all custom names, which is why registering them
 * here is not optional.
 *
 * `cn/config` is `cn`'s twin of `extendTailwindMerge`; `createCn` returns a
 * `cn` with the same signature. The groups below are the *value* groups, which
 * is what the token names actually mean. Colors need no registration: unknown
 * values already fall through to the color group, which is the right answer
 * for them.
 *
 * Regression-tested in `utils.spec.ts` — if a token is added to `theme.css`
 * without being added here, that test is what catches it.
 */
export const cn: (...inputs: ClassValue[]) => string = createCn({
  extend: {
    classGroups: {
      /* --text-* in theme.css */
      "font-size": [
        {
          text: [
            "display",
            "headline",
            "title",
            "body",
            "callout",
            "label",
            "caption",
            "mono",
            "mono-strong",
            "button",
          ],
        },
      ],
      /* --shadow-* in theme.css */
      shadow: [{ shadow: ["frost", "panel", "dialog"] }],
      /* Named component geometry must also yield to caller overrides. */
      h: [
        {
          h: [
            "control-sm",
            "control-md",
            "control-lg",
            "progress-sm",
            "progress-md",
            "progress-lg",
          ],
        },
      ],
      size: [{ size: ["icon-sm", "icon-md", "icon-lg"] }],
      rounded: [{ rounded: ["item"] }],
    },
  },
});

/**
 * A token's leading number, in the unit the token was written in: px as px,
 * durations as milliseconds.
 *
 * Custom properties are substituted, not computed, so the unit comes back as it
 * was authored — and a `450ms` in the source is `.45s` in the built sheet. A
 * duration therefore has to be converted rather than read at face value: 0.45 is
 * a dwell that has already elapsed, and anything comparing a token against a
 * clock counts in the milliseconds it was written in.
 */
export function tokenNumber(value: string): number | undefined {
  const number = Number.parseFloat(value);
  if (!Number.isFinite(number)) return undefined;
  return value.endsWith("ms") ? number : value.endsWith("s") ? number * 1000 : number;
}

/**
 * One observer of each kind per document, and one animation frame in which
 * everything they saw is answered.
 *
 * ## Why this exists
 *
 * `Squircle` used to build its own pair per instance, and register the
 * `MutationObserver` on the shape *and on every one of its ancestors* — that
 * being the only way a single observer sees the `class` a theme toggle writes
 * on `<html>`. With N surfaces on a page that is N observers, N ancestor walks
 * at mount, and, when the toggle lands, N separate callbacks each running its
 * own write/read/write against the layout engine.
 *
 * One observer on `documentElement` with `subtree: true` sees all of the same
 * signals. Coalescing what it saw into a single animation frame, and running
 * that frame in phases, turns those N forced recalculations into one.
 *
 * ## What counts as a signal
 *
 * A surface has to resample when anything that could change its *computed*
 * style changes, which is three separate things and not only the element:
 *
 *   - any attribute on the element itself, because `[data-disabled]` and
 *     friends are how variants are selected;
 *   - `class` or `style` on any ancestor, because that is how the cascade
 *     carries a theme, a scope, or a hover state down to it;
 *   - the viewport size and the colour scheme, because a media query can
 *     restyle it without touching a single attribute.
 *
 * `observeAppearance` covers all three. Box size is separate — it changes the
 * shape without changing a style — and is `observeSize`.
 */

/**
 * A subscriber, split into the phases of what it does to the layout engine.
 *
 * Reading a computed style after writing one forces the engine to recalculate
 * on the spot, so a subscriber that writes, reads, then writes again costs one
 * synchronous recalculation — and N of them interleaved cost N. Taking the
 * phases separately lets the batch land every write, then take every read, then
 * land every write, which costs one recalculation no matter how many surfaces
 * are in the batch.
 *
 * `measure` must not write and `prepare` must not read. That split is the whole
 * reason this interface is not just a callback.
 *
 * ## Why `release` is separate from `commit`
 *
 * A subscriber that suppresses transitions in order to sample a target style
 * has to turn them back on, and *when* it does that is not a detail: CSS starts
 * a transition by comparing the before-change style against the after-change
 * style at one style change event. Restoring `transition` in the same write
 * batch that lands the new values means the engine resolves both together, sees
 * a changed property with a live transition, and animates the write — a write
 * the subscriber only made to hide something.
 *
 * `release` runs after the batch has forced one recalculation, so those writes
 * are already resolved and re-enabling transitions compares equal values
 * against themselves. The batch pays one extra recalculation for all of its
 * subscribers, not one each; a subscriber with nothing to re-enable may omit
 * the phase entirely.
 *
 * ## Why `sample` comes before `prepare`
 *
 * Suppression that is any narrower than "all transitions off" has to be built
 * out of what the element already declares, and `prepare` cannot read it: by
 * the time the second subscriber prepares, the first has written, so every read
 * from there on forces its own recalculation. `sample` is the read-only phase
 * that runs before the batch has written anything, which is the one point where
 * that read costs the batch nothing beyond the recalculation it was going to
 * pay anyway.
 */
export interface AppearanceListener {
  /** Reads only, before the batch has written anything. */
  sample?(): void;
  /** Writes only: put the element into the state that is about to be read. */
  prepare(): void;
  /** Reads only. */
  measure(): void;
  /** Writes, and whatever follows from what `measure` read. */
  commit(): void;
  /** Writes, once `commit`'s have been resolved. Restores suppression. */
  release?(): void;
}

/**
 * Resolve everything written so far, so that a write which follows is compared
 * against it rather than batched with it. One forced recalculation, whatever
 * the batch holds — and the reason `release` exists.
 */
function resolve(view: View): void {
  void view.document?.documentElement?.offsetWidth;
}

/** Outside a batch — at mount, or after a render that changed the inputs. */
export function syncNow(element: Element, listener: AppearanceListener): void {
  listener.sample?.();
  listener.prepare();
  listener.measure();
  listener.commit();
  const view = element.ownerDocument.defaultView;
  if (view) resolve(view);
  listener.release?.();
}

/**
 * Written by the smooth-corner machinery onto the element it clips. Nothing in
 * ClaraLight's CSS selects on them, so a change is never a reason to resample.
 */
const IGNORED_ATTRIBUTES = new Set(["data-state", "data-slot"]);

/** The two attributes an ancestor can restyle a descendant through. */
const INHERITED_ATTRIBUTES = new Set(["class", "style"]);

/** `ownerDocument.defaultView`, which is the only window these ever touch. */
type View = Window & typeof globalThis;

interface Registry {
  appearance: Map<Element, Set<AppearanceListener>>;
  size: Map<Element, Set<AppearanceListener>>;
  /** Subscribers a signal named directly. */
  pending: Set<AppearanceListener>;
  /** `class`/`style` moved here; every subscriber beneath it is a subscriber. */
  branches: Set<Node>;
  /** A media query moved, which is every appearance subscriber at once. */
  everything: boolean;
  /** Whether the viewport and colour-scheme listeners are attached. */
  bound: boolean;
  /** Elements whose next attribute records are our own writes coming back. */
  settled: Set<Element>;
  mutation: MutationObserver | null;
  resize: ResizeObserver | null;
  scheme: MediaQueryList | null;
  onEnvironment: () => void;
  frame: number | null;
}

const registries = new WeakMap<View, Registry>();

function registryFor(view: View): Registry {
  const existing = registries.get(view);
  if (existing) return existing;
  const registry: Registry = {
    appearance: new Map(),
    size: new Map(),
    pending: new Set(),
    branches: new Set(),
    everything: false,
    bound: false,
    settled: new Set(),
    mutation: null,
    resize: null,
    scheme: null,
    onEnvironment: () => {
      registry.everything = true;
      schedule(view, registry);
    },
    frame: null,
  };
  registries.set(view, registry);
  return registry;
}

function schedule(view: View, registry: Registry) {
  if (registry.frame !== null) return;
  registry.frame = view.requestAnimationFrame(() => flush(view, registry));
}

function flush(view: View, registry: Registry) {
  registry.frame = null;
  const listeners = new Set(registry.pending);
  registry.pending.clear();
  const branches = [...registry.branches];
  registry.branches.clear();
  const everything = registry.everything;
  registry.everything = false;

  if (everything) {
    for (const set of registry.appearance.values()) {
      for (const listener of set) listeners.add(listener);
    }
  } else if (branches.length > 0) {
    // Walking down from the branch would mean knowing the subtree; asking each
    // subscriber whether it is under one is the same answer for a handful of
    // native calls, and it cannot go stale when an element is moved.
    for (const [element, set] of registry.appearance) {
      // Strictly beneath: a branch that *is* a subscriber was already offered
      // through the direct path, which is the only path `settle` can suppress.
      if (!branches.some((branch) => branch !== element && branch.contains(element))) continue;
      for (const listener of set) listeners.add(listener);
    }
  }

  if (listeners.size === 0) return;
  for (const listener of listeners) listener.sample?.();
  for (const listener of listeners) listener.prepare();
  for (const listener of listeners) listener.measure();
  for (const listener of listeners) listener.commit();
  resolve(view);
  for (const listener of listeners) listener.release?.();
  // Everything the phases just wrote is our own doing, not a new signal. Only
  // records queued during this synchronous pass are dropped: anything that
  // arrived before it was already delivered into `pending` and `branches`.
  registry.mutation?.takeRecords();
}

function mutationObserverFor(view: View, registry: Registry): MutationObserver | null {
  if (registry.mutation) return registry.mutation;
  if (typeof view.MutationObserver !== "function") return null;
  const root = view.document?.documentElement;
  if (!root) return null;
  const observer = new view.MutationObserver((records) => {
    let signalled = false;
    for (const record of records) {
      const name = record.attributeName;
      if (name === null || IGNORED_ATTRIBUTES.has(name)) continue;
      const target = record.target;
      const direct = registry.appearance.get(target as Element);
      // A settled element's records are the writes a synchronous sync just
      // made, arriving one microtask later. Suppressing its own resample but
      // not the branch beneath it keeps a nested surface hearing a class change
      // that genuinely happened here.
      if (direct && !registry.settled.has(target as Element)) {
        for (const listener of direct) registry.pending.add(listener);
        signalled = true;
      }
      if (INHERITED_ATTRIBUTES.has(name)) {
        registry.branches.add(target);
        signalled = true;
      }
    }
    // One synchronous sync queues a record per property it wrote, and they all
    // arrive in this one delivery, so the mark is cleared per batch not per
    // record.
    registry.settled.clear();
    if (signalled) schedule(view, registry);
  });
  observer.observe(root, { attributes: true, subtree: true });
  registry.mutation = observer;
  return observer;
}

function resizeObserverFor(view: View, registry: Registry): ResizeObserver | null {
  if (registry.resize) return registry.resize;
  if (typeof view.ResizeObserver !== "function") return null;
  const observer = new view.ResizeObserver((entries) => {
    for (const entry of entries) {
      const listeners = registry.size.get(entry.target);
      if (!listeners) continue;
      for (const listener of listeners) registry.pending.add(listener);
    }
    schedule(view, registry);
  });
  registry.resize = observer;
  return observer;
}

function teardown(view: View, registry: Registry) {
  if (registry.appearance.size > 0 || registry.size.size > 0) return;
  registry.mutation?.disconnect();
  registry.mutation = null;
  registry.resize?.disconnect();
  registry.resize = null;
  view.removeEventListener("resize", registry.onEnvironment);
  registry.scheme?.removeEventListener?.("change", registry.onEnvironment);
  registry.scheme = null;
  registry.bound = false;
  if (registry.frame !== null) {
    view.cancelAnimationFrame(registry.frame);
    registry.frame = null;
  }
  registry.pending.clear();
  registry.branches.clear();
  registry.settled.clear();
  registry.everything = false;
  registries.delete(view);
}

function subscribe(
  map: Map<Element, Set<AppearanceListener>>,
  element: Element,
  listener: AppearanceListener,
) {
  const existing = map.get(element);
  if (existing) {
    existing.add(listener);
    return false;
  }
  map.set(element, new Set([listener]));
  return true;
}

function unsubscribe(
  map: Map<Element, Set<AppearanceListener>>,
  element: Element,
  listener: AppearanceListener,
) {
  const listeners = map.get(element);
  if (!listeners) return false;
  listeners.delete(listener);
  if (listeners.size > 0) return false;
  map.delete(element);
  return true;
}

/**
 * Resample `listener` whenever anything that could change `element`'s computed
 * style changes: an attribute on it, `class` or `style` on an ancestor, the
 * viewport, or the colour scheme.
 */
export function observeAppearance(element: Element, listener: AppearanceListener): () => void {
  const view = element.ownerDocument.defaultView;
  if (!view) return () => {};
  const registry = registryFor(view);
  subscribe(registry.appearance, element, listener);
  mutationObserverFor(view, registry);
  // Bound once for the registry's whole life, not per subscriber: appearance
  // subscribers can drop to zero and come back while a size subscriber holds
  // the registry open, and re-binding there would strand the old query.
  if (!registry.bound) {
    registry.bound = true;
    view.addEventListener("resize", registry.onEnvironment);
    registry.scheme = view.matchMedia?.("(prefers-color-scheme: dark)") ?? null;
    registry.scheme?.addEventListener?.("change", registry.onEnvironment);
  }
  let released = false;
  return () => {
    if (released) return;
    released = true;
    unsubscribe(registry.appearance, element, listener);
    registry.pending.delete(listener);
    registry.settled.delete(element);
    teardown(view, registry);
  };
}

/** Resample `listener` whenever `element`'s box changes size. */
export function observeSize(element: Element, listener: AppearanceListener): () => void {
  const view = element.ownerDocument.defaultView;
  if (!view) return () => {};
  const registry = registryFor(view);
  const observer = resizeObserverFor(view, registry);
  if (!observer) return () => {};
  if (subscribe(registry.size, element, listener)) observer.observe(element);
  let released = false;
  return () => {
    if (released) return;
    released = true;
    if (unsubscribe(registry.size, element, listener)) observer.unobserve(element);
    registry.pending.delete(listener);
    teardown(view, registry);
  };
}

/**
 * Put `listener` into the next batch without an observer having seen anything —
 * for the signals that arrive as events rather than as mutations.
 */
export function requestSync(element: Element, listener: AppearanceListener): void {
  const view = element.ownerDocument.defaultView;
  if (!view) return;
  const registry = registries.get(view);
  if (!registry) return;
  registry.pending.add(listener);
  schedule(view, registry);
}

/**
 * Tell the shared observer that the attribute records `element` is about to
 * queue are ours. Used by a synchronous sync, which cannot drain the shared
 * observer's queue the way a batch can without swallowing other subscribers'
 * signals.
 */
export function settle(element: Element): void {
  const view = element.ownerDocument.defaultView;
  if (!view) return;
  const registry = registries.get(view);
  if (registry?.appearance.has(element)) registry.settled.add(element);
}

"use client";

import { parseBorder, parseBoxShadow } from "@lisse/core";
import { type EffectsConfig, useSmoothCorners } from "@lisse/react";
import {
  type ComponentProps,
  type CSSProperties,
  cloneElement,
  Fragment,
  isValidElement,
  type ReactNode,
  type Ref,
  type RefCallback,
  useEffect,
  useLayoutEffect,
  useMemo,
  useRef,
  useState,
} from "react";
import {
  type AppearanceListener,
  observeAppearance,
  observeSize,
  requestSync,
  settle,
  syncNow,
} from "@/lib/observers";
import { cn } from "@/lib/utils";

/**
 * ClaraLight's smooth-corner primitive.
 *
 * ## Why this exists instead of `corner-shape`
 *
 * Every ClaraLight corner is a smooth corner. On the web there are two ways
 * to draw that, and they are **different curve families that do not coincide**:
 *
 *   `corner-shape: superellipse()`  a true Lame superellipse, `squircle` == n=4.
 *                                   Chromium 139+ only; Safari and Firefox drop
 *                                   it at parse time.
 *   Figma corner smoothing          cubic Bezier shoulders bracketing a circular
 *                                   arc, `p = (1 + xi) * R`, residual arc
 *                                   `90 * (1 - xi)` degrees.
 *
 * ClaraLight follows the design, the design lives in Figma, and there the
 * second construction is the one drawn — it is also the same family as Apple's
 * `cornerCurve = .continuous`. So `corner-shape` is deliberately unused, and
 * `@lisse/react` emits this path in every engine instead, which means Safari,
 * Firefox and Chromium agree pixel for pixel rather than approximately.
 *
 * ## Why a hook and an explicit wrapper
 *
 * Lisse renders borders and shadows as **SVG overlays appended to an anchor
 * element**, because `clip-path` clips the element's own painted border and box
 * shadow to nothing. That anchor has to be a positioned box that tightly wraps
 * the shape, and `<SmoothCorners>` would otherwise invent one — which would
 * leave a `Card` no longer a direct grid or flex child.
 *
 * Owning the wrapper here keeps both halves addressable and their roles
 * explicit: `wrapperClassName` is layout, `className` is appearance. It also
 * lets a caller promote the wrapper into whatever layout slot the component
 * already occupied.
 *
 * ## The focus-ring problem
 *
 * `clip-path` crops `outline` too, so `:focus-visible` rings cannot live on the
 * clipped element. Components that need a ring put it on an ancestor instead —
 * see `button.tsx`. Surfaces like `Card` and the dialog panel draw the focus
 * inside themselves, so they are unaffected.
 *
 * ## Flat surfaces
 *
 * At radius 0 all of the above is machinery for drawing a rectangle. So a
 * surface that *measures* zero — `radius="none"`, an authored
 * `borderRadius: 0`, or a scope that zeroes the token — drops out of it: no
 * generated path, no SVG overlay, and the native `border` and `box-shadow`
 * paint themselves rather than being masked out and redrawn. The measurement
 * keeps running, so a surface that stops being flat picks the shape back up.
 *
 * The one thing that cannot lapse is the clip: it holds the content in, and it
 * establishes the backdrop root the scroll area's edge blur reads. A static
 * `clip-path: inset(0)` in `base.css` keeps both; that rule records what else
 * was measured as a substitute and rejected.
 */

/**
 * Corner radius tokens declared as `--radius-*` in theme.css.
 *
 * `none` is not merely `0px`: a surface that measures a zero radius stops
 * being a generated shape at all. See "Flat surfaces" above.
 */
export type RadiusToken = "none" | "control" | "medium" | "panel" | "sheet" | "dialog" | "capsule";

const useIsomorphicLayoutEffect = typeof window === "undefined" ? useEffect : useLayoutEffect;

export interface SquircleProps extends ComponentProps<"div"> {
  /** Which `--radius-*` token shapes the corners. */
  radius: RadiusToken;
  /**
   * Figma's `xi`. `0` is a plain circular arc identical to `border-radius`;
   * `1` removes the arc entirely and leaves only Beziers. Defaults to
   * `--cl-corner-smoothing`, which is Figma's own default.
   */
  smoothing?: number;
  /**
   * Classes for the wrapper: grid/flex placement, transforms, and the focus
   * ring. This element — not the clipped one — participates in the caller's
   * layout, and it is also what has to move when the shape moves.
   */
  wrapperClassName?: string;
  /**
   * The wrapper, which is the element a caller's transform belongs on — and the
   * only way to observe the box the shape is clipped to. `ref` is the shape's,
   * because that is what a caller interacts with; this is the box around it.
   */
  wrapperRef?: Ref<HTMLDivElement> | undefined;
  /**
   * Put the ClaraLight focus ring on the wrapper.
   *
   * The ring cannot live on the shape: `clip-path` crops `outline` to nothing.
   * Measured, a 2px ring at 2px offset goes from 436 lit pixels to 0. So the
   * ring goes on the wrapper and is driven by `:has(> [data-cl-squircle]
   * :focus-visible)` in `base.css`, which keeps the browser's keyboard/pointer
   * heuristic and preserves the 2px offset the design asks for.
   *
   * Off by default because surfaces do not take focus.
   */
  ring?: boolean | "field";
  /**
   * Merge the clipped element's props onto a single child instead of rendering
   * a `div` around `children`.
   *
   * Needed because the clipped element is often a primitive that must own its
   * own tag — Base UI's `Button`, `Input` and `Select.Trigger` all render the
   * real interactive element and carry its behaviour. Wrapping them in a `div`
   * would leave the interactive element inside an inert box.
   */
  asChild?: boolean;
  /** Classes for the shape itself: fill, border, shadow, padding. */
  className?: string;
  children?: ReactNode;
}

export function Squircle({
  radius,
  smoothing,
  wrapperClassName,
  wrapperRef,
  ring = false,
  asChild = false,
  className,
  children,
  ref: forwardedRef,
  style,
  ...props
}: SquircleProps) {
  const [element, setElement] = useState<HTMLDivElement | null>(null);
  // Lisse 0.7.2 binds its observer/effects lifecycle to the ref object, not
  // ref.current. Replace that object only when the actual DOM node changes
  // (asChild tag/key changes or a primitive temporarily rendering null).
  const ref = useMemo(() => ({ current: element }), [element]);
  const internalWrapperRef = useRef<HTMLDivElement>(null);
  const mergedWrapperRef = useMemo(() => composeRefs(internalWrapperRef, wrapperRef), [wrapperRef]);
  const border = `var(--radius-${radius})`;
  const child = asChild ? getShapeChild(children) : undefined;
  const childProps = child?.props as ComponentProps<"div"> | undefined;
  const childRef = childProps?.ref;
  const mergedRef = useMemo(
    () => composeRefs(setElement, forwardedRef, childRef),
    [forwardedRef, childRef],
  );
  const mergedStyle = { ...style, ...childProps?.style };
  const mergedClassName = cn(className, childProps?.className);
  // A uniform authored radius overrides the token for SSR, clipping and SVG.
  const renderedRadius = mergedStyle.borderRadius ?? border;
  const measuredRadius =
    typeof renderedRadius === "number" ? `${renderedRadius}px` : renderedRadius;
  // Every declarative input that can move the shape's computed style. A render
  // that leaves all of them alone leaves the measurement alone too — anything
  // else that could have moved arrives as an observer signal, not as a render.
  const syncKey = JSON.stringify([measuredRadius, smoothing, mergedStyle, mergedClassName]);
  const appearance = useAppearance(ref, measuredRadius, smoothing, mergedStyle, syncKey);
  // Only once the radius has actually been read: the pre-measurement state is
  // also a zero, and treating that as flat would square every corner for the
  // render between mount and the first measurement.
  const flat = appearance.measured && appearance.corners.radius === 0;
  // Lisse keys its whole lifecycle on the ref object and does nothing with one
  // that holds null, so this is also how the shape is handed back: swapping the
  // object runs its cleanup, which removes the overlays and restores the clip.
  const emptyRef = useRef<HTMLElement | null>(null);
  const cornersRef = flat ? emptyRef : ref;

  // 0.7.2's autoEffects only extracts at mount. Explicit effects are compared
  // by value on every commit, so theme/variant changes update the existing SVG.
  useSmoothCorners(cornersRef, appearance.corners, {
    wrapperRef: internalWrapperRef,
    autoEffects: false,
    effects: appearance.effects,
    // 0.7.2 otherwise keeps an existing shadow handle with DEFAULT_SHADOW
    // when an explicit shadow disappears (e.g. panel -> control).
    skipShadowHandle: !appearance.effects.shadow,
    fallbackBorderRadius: measuredRadius,
  });

  // Swapping Lisse's ref object runs its cleanup, and that cleanup restores the
  // inline `border-radius` it snapshotted when it mounted — one radius stale by
  // the time the surface has gone flat. React will not rewrite a value it did
  // not itself change, so re-assert it here. Declared after `useSmoothCorners`,
  // which is what puts this effect after that cleanup. Shaped surfaces are left
  // alone: there, Lisse owns the property and deliberately clears it.
  useIsomorphicLayoutEffect(() => {
    if (flat && ref.current) ref.current.style.borderRadius = measuredRadius;
  }, [ref, flat, measuredRadius]);

  const shapeProps = {
    ...props,
    ref: mergedRef,
    "data-cl-squircle": radius,
    // Drives the static rectangle clip in base.css, which is the part of the
    // generated shape a flat surface still needs.
    "data-cl-flat": flat ? "" : undefined,
    style: { ...mergedStyle, borderRadius: renderedRadius },
    className: mergedClassName,
  };

  return (
    <div
      ref={mergedWrapperRef}
      style={{ "--cl-squircle-radius": measuredRadius } as CSSProperties}
      className={cn(
        "relative",
        ring === true && "cl-squircle-root",
        ring === "field" && "cl-squircle-root cl-squircle-field",
        wrapperClassName,
      )}
    >
      {child ? cloneElement(child, shapeProps) : <div {...shapeProps}>{children}</div>}
    </div>
  );
}

function getShapeChild(child: ReactNode) {
  if (!isValidElement<ComponentProps<"div">>(child) || child.type === Fragment) {
    throw new Error("Squircle: `asChild` expects exactly one non-Fragment React element.");
  }
  return child;
}

/** React 19: a cleanup-returning callback must not also receive null. */
export function composeRefs<T>(...refs: (Ref<T> | undefined)[]): RefCallback<T> {
  return (node) => {
    const cleanups = refs.map((ref) => {
      if (typeof ref === "function") {
        const cleanup = ref(node);
        return typeof cleanup === "function" ? cleanup : () => ref(null);
      }
      if (ref) {
        ref.current = node;
        return () => {
          ref.current = null;
        };
      }
      return undefined;
    });
    return () => {
      for (const cleanup of cleanups) cleanup?.();
    };
  };
}

const hiddenStyles = {
  "border-top-color": "transparent",
  "border-right-color": "transparent",
  "border-bottom-color": "transparent",
  "border-left-color": "transparent",
  "box-shadow": "none",
} as const;

type HiddenProperty = keyof typeof hiddenStyles;
type SavedStyle = { value: string; priority: string };

/**
 * The properties a measurement pass writes, neutralised.
 *
 * Sampling has to move three things the author may well be transitioning: the
 * border colour and the shadow, which are lifted out of the mask so they can be
 * read, and the radius, which is overwritten with a probe. A transition on any
 * of them would hand `measure` an interpolated value instead of the target one.
 *
 * Appending rather than replacing is what keeps the suppression this narrow.
 * `transition` takes a list, and where a property appears twice the last entry
 * wins — so the author's own list stays in force, and only these three are
 * pinned to zero. Blanking `transition` instead would be simpler and wrong: it
 * cancels whatever is mid-flight, and a pass is most often triggered by hover
 * or focus, which is exactly when the fill is one frame into its fade.
 */
const SAMPLED_PROPERTIES = "border-color 0s, box-shadow 0s, border-radius 0s";

/**
 * The author's `transition` with the sampled properties pinned to zero.
 *
 * Chromium serialises the shorthand to the empty string when the longhands
 * cannot round-trip through it, and there is nothing to append to then — so
 * that case falls back to suppressing everything, which is what this replaced.
 */
function suppress(authored: string | null): string {
  return authored ? `${authored}, ${SAMPLED_PROPERTIES}` : "none";
}

/**
 * Read the actual shape's cascade, not documentElement: local themes, rem/calc
 * radii, inline tokens and nested light/dark scopes all work.
 *
 * Every signal arrives through the shared observers in `observers.ts`, and the
 * work is handed over as three phases rather than one callback. A resample has
 * to write a probe radius before it can read one back, and reading a computed
 * style after writing one forces the engine to recalculate on the spot — so a
 * page of surfaces answering a theme toggle one at a time costs one forced
 * recalculation each. Split into phases, the batch writes every probe, takes
 * every reading, then puts every element back, and costs one for all of them.
 *
 * There is still no frame polling: nothing runs unless something moved.
 */
function useAppearance(
  ref: { current: HTMLElement | null },
  border: string,
  smoothing: number | undefined,
  style: CSSProperties,
  syncKey: string,
) {
  const [appearance, setAppearance] = useState({
    // Not design defaults: SSR uses the CSS border-radius, before measurement.
    measured: false,
    corners: { radius: 0, smoothing: 0 },
    effects: {} as EffectsConfig,
  });
  const latest = useRef({ border, smoothing, style, syncKey });
  latest.current = { border, smoothing, style, syncKey };
  const syncRef = useRef<(() => void) | null>(null);
  /** The key the element was last measured at, so a no-op render stays one. */
  const syncedKey = useRef<string | null>(null);

  useIsomorphicLayoutEffect(() => {
    const element = ref.current;
    if (!element) return;
    const view = element.ownerDocument.defaultView;
    if (!view) return;
    const saved = new Map<HiddenProperty, SavedStyle>();
    let previousStyle = "";
    const restore = () => {
      for (const [property, source] of saved) {
        // An imperative or React inline update takes precedence over our mask.
        if (
          element.style.getPropertyValue(property) === hiddenStyles[property] &&
          element.style.getPropertyPriority(property) === "important"
        ) {
          element.style.setProperty(property, source.value, source.priority);
        }
      }
      saved.clear();
    };

    /** The radius `prepare` displaced and `commit` has to put back. */
    let probe: { radius: string } | null = null;
    /** What `measure` read, for `commit` to act on. */
    let sample: { radius: number; smoothing: number; effects: EffectsConfig } | null = null;
    /**
     * The authored `transition`, displaced by `prepare` and put back by
     * `release` — never by `commit`.
     *
     * Masking the border and shadow is a style change like any other, so a
     * `transition` that is live in the same batch animates it: a field that
     * transitions `border-color` fades its real 1px border out from under the
     * SVG one instead of having it hidden. Worse, the fade ends in a
     * `transitionend`, which is itself a resample signal — so the surface
     * re-masks, re-fades, and flickers for as long as it is mounted. Restoring
     * only once the batch has resolved the mask compares transparent against
     * transparent and starts nothing.
     *
     * Suppressing and restoring are the same pair of writes whatever the
     * measurement found, so they sit in the two phases that always run, not in
     * the one that can bail out early.
     */
    let suppressed: { value: string; priority: string } | null = null;
    /** What `sample` read, for `prepare` to build its suppression out of. */
    let authoredTransition: string | null = null;

    const listener: AppearanceListener = {
      sample() {
        // Read before the batch writes anything, so the element still reports
        // the cascade's own transition rather than a previous pass's override.
        authoredTransition = view.getComputedStyle(element).transition || null;
      },

      prepare() {
        probe = { radius: element.style.borderTopLeftRadius };
        // Sample target CSS, not a transition starting from our own writes.
        suppressed ??= {
          value: element.style.getPropertyValue("transition"),
          priority: element.style.getPropertyPriority("transition"),
        };
        element.style.setProperty("transition", suppress(authoredTransition), "important");
        restore();
        const current = latest.current;
        // React may write the same value as our mask (e.g. shadow -> none).
        // Reconcile declarative border/shadow styles before a new snapshot.
        const authored = JSON.stringify(current.style);
        if (authored !== previousStyle) {
          if (previousStyle !== "") {
            const source = element.ownerDocument.createElement("div").style;
            for (const [key, value] of Object.entries(current.style)) {
              if (/^border.*(?:Color)?$/.test(key) && !/Width|Radius/.test(key)) {
                source.setProperty(
                  key.replace(/[A-Z]/g, (letter) => `-${letter.toLowerCase()}`),
                  String(value),
                );
              }
            }
            source.boxShadow = current.style.boxShadow ?? "";
            for (const property of Object.keys(hiddenStyles) as HiddenProperty[]) {
              element.style.setProperty(property, source.getPropertyValue(property));
            }
          }
          previousStyle = authored;
        }
        // Let the browser resolve units, calc() and inherited custom properties.
        element.style.borderTopLeftRadius = current.border;
      },

      measure() {
        if (!probe) return;
        const current = latest.current;
        const computed = view.getComputedStyle(element);
        const radiusValue = computed.borderTopLeftRadius;
        const radius = radiusValue.endsWith("%")
          ? (Number.parseFloat(radiusValue) * Math.min(element.clientWidth, element.clientHeight)) /
            100
          : Number.parseFloat(radiusValue);
        const tokenSmoothing = Number.parseFloat(
          computed.getPropertyValue("--cl-corner-smoothing"),
        );
        sample = {
          radius: Number.isFinite(radius) ? Math.max(0, radius) : 0,
          smoothing: Math.min(
            1,
            Math.max(
              0,
              current.smoothing ?? (Number.isFinite(tokenSmoothing) ? tokenSmoothing : 0),
            ),
          ),
          effects: {
            innerBorder: parseBorder(element, computed),
            ...parseBoxShadow(computed.boxShadow),
          },
        };
      },

      commit() {
        const displaced = probe;
        const measured = sample;
        probe = null;
        sample = null;
        if (!displaced || !measured) return;
        element.style.borderTopLeftRadius = displaced.radius;
        if (element.style.clipPath) {
          element.style.borderRadius = "";
        }
        const next = {
          measured: true,
          corners: { radius: measured.radius, smoothing: measured.smoothing },
          effects: measured.effects,
        };
        // A flat surface paints its own border and shadow, so there is nothing
        // to hide. `prepare` already restored whatever the last pass masked.
        const flat = measured.radius === 0;
        for (const property of flat ? [] : (Object.keys(hiddenStyles) as HiddenProperty[])) {
          if (
            property === "box-shadow"
              ? next.effects.shadow || next.effects.innerShadow
              : next.effects.innerBorder
          ) {
            saved.set(property, {
              value: element.style.getPropertyValue(property),
              priority: element.style.getPropertyPriority(property),
            });
            // Keep border widths/layout; Lisse's autoEffects instead sets border:0.
            element.style.setProperty(property, hiddenStyles[property], "important");
          }
        }
        syncedKey.current = latest.current.syncKey;
        setAppearance((previous) =>
          JSON.stringify(previous) === JSON.stringify(next) ? previous : next,
        );
      },

      release() {
        const displaced = suppressed;
        suppressed = null;
        if (!displaced) return;
        element.style.setProperty("transition", displaced.value, displaced.priority);
      },
    };

    /**
     * React drives this one, so it stays synchronous: a variant change has to
     * be measured in the commit that caused it, not a frame later.
     */
    const sync = () => {
      syncNow(element, listener);
      settle(element);
    };

    const onInteraction = (event: Event) => {
      if (event.type === "transitionend" || event.type === "animationend") {
        if (event.target !== element) return;
      } else if (event.type === "pointerover" || event.type === "pointerout") {
        const related = (event as PointerEvent).relatedTarget;
        if (related instanceof view.Node && element.contains(related)) return;
      }
      // Crossing a boundary fires `pointerout` here and `pointerover` there in
      // the same tick; the batch is what keeps that a single measurement pass.
      requestSync(element, listener);
    };
    const events = [
      "pointerover",
      "pointerout",
      "focusin",
      "focusout",
      "transitionend",
      "animationend",
    ];

    let unobserveAppearance: (() => void) | undefined;
    let unobserveSize: (() => void) | undefined;
    const cleanup = () => {
      unobserveAppearance?.();
      unobserveSize?.();
      for (const event of events) element.removeEventListener(event, onInteraction);
      syncRef.current = null;
      syncedKey.current = null;
      listener.release?.();
      restore();
    };
    try {
      syncRef.current = sync;
      unobserveAppearance = observeAppearance(element, listener);
      unobserveSize = observeSize(element, listener);
      for (const event of events) element.addEventListener(event, onInteraction);
      sync();
      return cleanup;
    } catch (error) {
      cleanup();
      throw error;
    }
  }, [ref]);

  // Only the inputs React itself can change need a synchronous resample; a
  // parent re-render or new children cannot move the cascade, and everything
  // that can is a signal the shared observers already carry.
  useIsomorphicLayoutEffect(() => {
    if (syncedKey.current === syncKey) return;
    syncRef.current?.();
  }, [syncKey]);
  return appearance;
}
